%[text] Test of mixed models, based on observed variables! 
%[text] Community type effect, find which model works better 
%[text] - Depth only
%[text] - Depth Depth|ClassID
%[text] - Depth Depth|ClassID Depth|Year
%[text] - Depth Depth|ClassID Depth|Year Depth|Station   \
%[text] Temp DOY effect 
%[text] - Depth Temp Doy
%[text] - Depth Temp Doy  Depth Temp Doy |Year
%[text] - Depth Depth|ClassID Depth|Year Depth|Station   \
%[text] Midex effect. Include random factors for previous 
%[text] - Depth Temp Doy  Depth|ClassID Depth|Year  \
%[text] 
%[text] 
%Load data 

proj_Initialize %[output:831106b3] %[output:5226d3fe] %[output:34a69759] %[output:5401c4e8] %[output:428f70ab] %[output:6a687dd8] %[output:2275dd14] %[output:0bd861c5]

predictors = {'Lon', 'Month_doy', 'Depth'};

%Load diffusion map clusters
tDMC = readtable(fullfile(HGP.Data.Path2ResultsData, 'Samples_DMC_clustID_obsrvpred.xlsx'));
tStPredictors.ClustID = categorical(tDMC.ClustID);
%%mean Depth =  41.5035
%tStPredictors.Depth = tStPredictors.Depth - mean(tStPredictors.Depth);
%tStPredictors.ClustID_predicted = categorical(tDMC.ClustID_predicted);

%Remove nans
tStPredictors = tStPredictors(~isnan(tStPredictors.chlorophyll_a_0), :);

%% transform the response
alpha =0.25;
%alpha =1;
var_tranf = @(y) y.^alpha ;
inv_var_tranf = @(tranf_y) tranf_y.^(1/alpha);
%[Y, lambda] = boxcox(tStPredictors.chlorophyll_a_0);
% var_tranf = @(y) log10(y);
%inv_var_tranf = @(tranf_y) 10.^tranf_y;
tStPredictors.transfChl = var_tranf(tStPredictors.chlorophyll_a_0);
figure(1)
clf %[output:7256258c]
histogram(tStPredictors.transfChl) %[output:7256258c]
%%
%[text] ## mixed model for chl (Depth, ClassID)
%[text] How does slope depend on the class ? 
%[text] Do we need year/cruise as a random variable? 
%[text] - Depth only
%[text] - Depth Depth|ClassID
%[text] - Depth Depth|ClassID Depth|Year
%[text] - Depth Depth|ClassID Depth|Year Depth|Station   \
%[text] ### Depth only 
% Fixed-effect-only model for marginal line
mxD = fitlme(tStPredictors, 'transfChl ~ Depth')  % %[output:6a747076]
mxD_iY = fitlme(tStPredictors, 'transfChl ~ Depth+ (1|Year)') %[output:0e1e0f10]
lme_results(mxD_iY) %[output:6c5efdf1]
%[text] ### Depth and class
mxD_iCl = fitlme(tStPredictors, 'transfChl ~ Depth + (1|ClustID)')  %rand intercept %[output:7786a9d8]
mxD_sCl = fitlme(tStPredictors, 'transfChl ~ Depth + (Depth-1|ClustID)');%rand slope 
mxD_fCl = fitlme(tStPredictors, 'transfChl ~ Depth + (Depth|ClustID)');%rand int+slope 
%disp(lme_De)
%[text] ### Depth and class
compare(mxD, mxD_iCl) %rand intercept  %[output:0270749f]
compare(mxD, mxD_sCl) %rand slope  %[output:2db57da4]
compare(mxD, mxD_fCl) %full  %[output:24d4d6a6]
%[text] **Conclusion**: **Keep random intercept for Depth,  mxD\_iCl: transfChl ~ 1 + Depth + (1 | ClustID)**
rsD_iCl = lme_results(mxD_iCl) %[output:09ff38a7]
%%
%[text] ### Depth and class and year/cruise
mxD_iCliY = fitlme(tStPredictors, 'transfChl ~ Depth + (1|ClustID) + (1|Year)');  %rand intercept
compare(mxD_iCl, mxD_iCliY) %add year %[output:71cd64d6]

mxD_iCliCr = fitlme(tStPredictors, 'transfChl ~ Depth + (1|ClustID) + (1|Cruise)');  %rand intercept
compare(mxD_iCl, mxD_iCliCr) %add year %[output:6a3940ea]
mxD_iCliCriSt = fitlme(tStPredictors, 'transfChl ~ Depth + (1|ClustID) + (1|Cruise) + (1|HGStation)');  %rand intercept
compare(mxD_iCliCr, mxD_iCliCriSt) %adding station provides a minimal reduction of AIC and is not significant, p>0.05 %[output:91ffb2ec]
%[text] **We can keep Cruise as a random factor; mxD\_iCliCr: transfChl ~ 1 + Depth + (1 | ClustID) + (1 | Cruise)**
rsD_iCliCr = lme_results(mxD_iCliCr) %[output:7546f90d]
(1-rsD_iCliCr.Res_Std/rsD_iCl.Res_Std)*100 %% improvement 6%  %[output:3e8ed21f]
%%
%[text] Compare std of Depth intercepts for Class ID with and without cruise 
 [statD_iCl, stdD_iCl] = lme_randeff(mxD_iCl, '(Intercept)', 'ClustID'); %Just class
 disp(stdD_iCl) %[output:28c29ed1]
 [statD_iCliCr, stdD_iCliCr] = lme_randeff(mxD_iCliCr, '(Intercept)', 'ClustID'); %Just class and cruise as random
 disp(stdD_iCliCr) %[output:68249a43]
figure %[output:5c0c7f99]
xInd = 1:size(statD_iCliCr, 1);
errorbar(xInd+0.2, statD_iCl.Estimate, statD_iCl.Estimate-statD_iCl.Lower, statD_iCl.Upper-statD_iCl.Estimate); %[output:5c0c7f99]
hold on  %[output:5c0c7f99]
errorbar(xInd, statD_iCliCr.Estimate, statD_iCliCr.Estimate-statD_iCliCr.Lower, statD_iCliCr.Upper-statD_iCliCr.Estimate); %[output:5c0c7f99]
legend({'Type ID', 'Type and cruise'}) %[output:5c0c7f99]
%[text] Both with and without cruise as random factor work quite good. The deviations in intercepts from zero are significant . 
%%
%[text] ### Selected model 
%[text] We selected the model with **Class and Cruise as random variables**. For this model we get 
mxD_iCliCr %[output:5c39e1fe]
lme_results(mxD_iCliCr) %[output:384a4058]
%[text] 
%%
%[text] ## Test of Depth, Temp, DOY effects 
%[text] Temp DOY effect 
%[text] - Depth Temp Doy
%[text] - Depth Temp Doy  1|Crusie \
mxDTDY = fitlme(tStPredictors, 'transfChl ~ Depth + temp_imputed + Month_doy');  %
reDTDY = lme_results(mxDTDY) %[output:115c37e5]
mxDTDY_iCl = fitlme(tStPredictors, 'transfChl ~ Depth + temp_imputed + Month_doy + (1|ClustID)');  %
reDTDY_iCl = lme_results(mxDTDY_iCl) %[output:3afe525d]
compare(mxDTDY, mxDTDY_iCl)  %[output:5c21fd9e]
%[text] Adding Type ID to D, T, Doy is significant and improves accuracy `Res_Std: 0.1741`
mxDTDY_iCliCr = fitlme(tStPredictors, 'transfChl ~ Depth + temp_imputed + Month_doy + (1|ClustID) + (1|Cruise)');  %
reDTDY_iCliCr = lme_results(mxDTDY_iCliCr) %[output:36ce69b1]
compare(mxDTDY_iCl, mxDTDY_iCliCr) %[output:8742ae2e]
%[text] Adding Cruise ID is also fine
mxDTDY_iCr = fitlme(tStPredictors, 'transfChl ~ Depth + temp_imputed + Month_doy + (1|Cruise)');  %
reDTDY_iCr = lme_results(mxDTDY_iCr) %[output:3d186a15]
compare(mxDTDY_iCr, mxDTDY_iCliCr) %[output:67086632]
%[text] Model with Class and Cruise as r.f. is better than a model with class or cruise only. So **we keep mxDTDY\_iCliCr** 
compare(mxD_iCliCr, mxDTDY_iCliCr)  %comparison of (Depth+(1|ClustID)+(1|Cruise)) with  (Depth+Temp+DOY + (1|ClustID)+(1|Cruise)) %[output:87a343ab]
%[text] However adding temperature and doy (although significant does not add much in terms of `AIC BIC`)
%[text] The standard deviations 
reD_iCliCr = lme_results(mxD_iCliCr) %[output:99a7d5f8]
reDTDY_iCliCr = lme_results(mxDTDY_iCliCr) %[output:6a8a456e]
%[text] These two models have similar R^2 and similar error 
%%
%[text] ## Test if adding other fixed parameters add something 
mxDTDYLon = fitlme(tStPredictors, 'transfChl ~ Depth + temp_imputed + Month_doy +Lon')  %Long is not significant  %[output:92a2752a]
mxDTDYLat = fitlme(tStPredictors, 'transfChl ~ Depth + temp_imputed + Month_doy + Lat')  %Long is not significant  %[output:3de25d74]
%[text] Conclusion: If we know temperature and Doy **we do not need latitude or longitude** 
%%
%[text] **We choose the model with** 
%[text] 
tbl = tStPredictors;
tbl.ClustID = categorical(tbl.ClustID);
tbl.Cruise  = categorical(tbl.Cruise);
lmePlotD = fitlme(tbl, "transfChl ~ Depth", "FitMethod","REML");
lmePlotiCl = fitlme(tbl, "transfChl ~ Depth + (1|ClustID)", "FitMethod","REML");
Cl = categories(tbl.ClustID);
nCl = numel(Cl);
clrs =f_Clrs_fresh(HGP.dmCluster.NumComponents);

d = linspace(min(tbl.Depth), 100, 150)';

[fg, MaxFigure] = addFindFigure('mixModChl', MaxFigure, [10, 20,  1279 552], 'normal', 'on'); %[output:5a3fa26d]
tiledlayout(2, 4, "Padding","compact", "TileSpacing","compact") %[output:5a3fa26d]
for k = 1:nCl %[output:group:079adea0]
    ax = nexttile(k); %[output:5a3fa26d]
    ax.YDir = "reverse";
    newT = table();
    newT.Depth   = d;
    newT.ClustID = categorical(repmat(Cl(k), numel(d), 1), Cl);

    [yhatD] = predict(lmePlotD, newT, "Alpha",0.05); 
    yhatD = inv_var_tranf(yhatD);

    [yhatDCl, yCI] = predict(lmePlotiCl, newT, "Alpha",0.05);
    yhatDCl = inv_var_tranf(yhatDCl);
    yCI = inv_var_tranf(yCI);
    yBand = [d; flipud(d)];
    xBand = [yCI(:,1); flipud(yCI(:,2))];
    p = patch(ax, xBand, yBand, clrs(k,:));
    p.FaceAlpha = 0.20; p.EdgeColor = 'none';
    p.Annotation.LegendInformation.IconDisplayStyle = 'off';
    hold on
    plot(ax, yhatDCl, d, 'Color', clrs(k,:), 'LineWidth', 3);
    plot(ax, yhatD, d, 'Color', [1,1,1]*0.5, 'LineStyle', '--', 'LineWidth', 1);
    ind = tbl.ClustID == Cl(k);
    s = scatter(ax, tbl.chlorophyll_a_0(ind), tbl.Depth(ind), 20, clrs(k,:), "filled");
    s.MarkerFaceAlpha = 0.2;
    xlim([0.01, 10])
    ylim([0, 100])
    ax.XAxis.Scale = "log";
    hold off
    ylabel("Depth (m)");
    xlabel("Chlorophyll-a (\mu g/L)");
    legend(["Type " + Cl(k), "mean"], "Location","best", "Interpreter","none");
end %[output:group:079adea0]
 AddLetters2Plots(fg,  'HShift', -0.03, 'VShift', 0.0, 'Location', 'NorthEast');


